#include <condition_variable>
#include <cstddef>
#include <functional>
#include <future>
#include <memory>
#include <mutex>
#include <queue>
#include <set>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

class Pool {
public:
    explicit Pool(int worker_count) {
        for (int i = 0; i < worker_count; ++i)
            workers_.emplace_back([this](std::stop_token stop) {
                while (true) {
                    std::function<void()> job;
                    {
                        std::unique_lock lock(mutex_);
                        // false means the stop was requested rather than work arriving.
                        if (!ready_.wait(lock, stop, [this] { return !jobs_.empty(); })) return;
                        job = std::move(jobs_.front());
                        jobs_.pop();
                    }
                    job();                      // lock released: other workers can proceed
                }
            });
    }

    template <class F>
    auto submit(F f) -> std::future<decltype(f())> {
        using Result = decltype(f());

        auto task = std::make_shared<std::packaged_task<Result()>>(std::move(f));
        std::future<Result> result = task->get_future();   // before it can be run

        {
            std::scoped_lock lock(mutex_);
            jobs_.emplace([task] { (*task)(); });
        }
        ready_.notify_one();
        return result;
    }

    std::size_t worker_count() const { return workers_.size(); }

private:
    std::mutex mutex_;
    std::condition_variable_any ready_;
    std::queue<std::function<void()>> jobs_;
    std::vector<std::jthread> workers_;
};
